215		}
216		header := fmt.Sprintf("%s Checkpoint push: %s%d commits, %d sessions",
217			styles.dim("[entire]"), branchLabel, opts.TotalCommits, len(summaries))
218		lines = append(lines, header)
219	
220		displayed := summaries
221		remaining := 0
222		if len(summaries) > maxDisplayedPushSessions {
223			displayed = summaries[:maxDisplayedPushSessions]
224			remaining = len(summaries) - maxDisplayedPushSessions
225		}
226	
227		for i, s := range displayed {
228			isLast := i == len(displayed)-1 && remaining == 0
229			connector := "├─"
230			if isLast {
231				connector = "└─"
232			}
233			cpLabel := fmt.Sprintf("%d checkpoints", s.CheckpointCount)
234			if s.CheckpointCount == 1 {
235				cpLabel = "1 checkpoint"
236			}
237			timeLabel := formatPushTimeRange(s.EarliestTime, s.LatestTime)
238			line := fmt.Sprintf("         %s %s  %s  %s",
239				styles.dim(connector), s.SessionID, styles.dim(cpLabel), styles.dim("("+timeLabel+")"))
240			lines = append(lines, line)
241		}
242	
243		if remaining > 0 {
244			lines = append(lines, fmt.Sprintf("         %s %s",
245				styles.dim("├─"), styles.dim(fmt.Sprintf("... and %d more sessions", remaining))))
246			oldest := summaries[len(summaries)-1]
247			lines = append(lines, fmt.Sprintf("         %s %s",
248				styles.dim("└─"), styles.dim("(oldest: "+formatPushDate(oldest.EarliestTime)+")")))
249		}
250	
251		return lines
252	}
253	
254	func parseGitProgressLine(line string) *gitProgressEvent {
255		trimmed := strings.TrimSpace(line)
256	
257		if m := gitEnumeratingRE.FindStringSubmatch(trimmed); m != nil {
258			total, err := strconv.Atoi(m[1])
259			if err != nil {
260				return nil
261			}
262			return &gitProgressEvent{
263				Phase: gitProgressPhaseCounting,
264				Total: total,
265				Done:  strings.Contains(trimmed, "done"),
266			}
267		}
268	
269		if m := gitCountingRE.FindStringSubmatch(trimmed); m != nil {
270			return parsePercentGitProgressEvent(gitProgressPhaseCounting, m, trimmed)
271		}
272		if m := gitCompressingRE.FindStringSubmatch(trimmed); m != nil {
273			return parsePercentGitProgressEvent(gitProgressPhaseCompressing, m, trimmed)
274		}
275		if m := gitWritingRE.FindStringSubmatch(trimmed); m != nil {
276			event := parsePercentGitProgressEvent(gitProgressPhaseWriting, m, trimmed)
277			if bm := gitWritingBytesRE.FindStringSubmatch(trimmed); bm != nil {
278				event.Bytes = bm[1]
279				if len(bm) > 2 {
280					event.Speed = bm[2]
281				}
282			}
283			return event
284		}
285	
286		return nil
287	}
288	
289	func parsePercentGitProgressEvent(phase gitProgressPhase, m []string, trimmed string) *gitProgressEvent {
290		percent, err := strconv.Atoi(m[1])
291		if err != nil {
292			return nil
293		}
294		current, err := strconv.Atoi(m[2])
295		if err != nil {
296			return nil
297		}
298		total, err := strconv.Atoi(m[3])
299		if err != nil {
300			return nil
301		}
302		return &gitProgressEvent{
303			Phase:   phase,
304			Percent: percent,
305			Current: current,
306			Total:   total,
307			Done:    strings.Contains(trimmed, "done"),
308		}
309	}
310	
311	// gitProgressStreamer is an io.Writer that live-parses git `--progress`
312	// stderr bytes as they arrive, without waiting for the push to finish. git
313	// emits progress as segments separated by '\r' (in-place updates) or '\n'
314	// (a completed line, e.g. the final "done." for a phase). Write accumulates
315	// bytes across calls — a chunk boundary can land mid-line — and parses each
316	// completed segment as soon as its terminator arrives, invoking onEvent for
317	// every line that parses to a non-nil *gitProgressEvent. Leftover partial
318	// bytes (after the last terminator in the chunk) are buffered for the next
319	// Write. Not safe for concurrent Write calls; callers must serialize writes
320	// (e.g. a single git stderr pipe copied by one goroutine).
321	type gitProgressStreamer struct {
322		buf     []byte
323		onEvent func(*gitProgressEvent)
324	}
325	
326	// Write implements io.Writer. It never returns an error — parse failures are
327	// simply skipped — so it never causes the underlying io.MultiWriter copy (see
328	// checkpoint/remote.PushOptions.ProgressWriter) to abort the push.
329	func (s *gitProgressStreamer) Write(p []byte) (int, error) {
330		s.buf = append(s.buf, p...)
331	
332		start := 0
333		for i, b := range s.buf {
334			if b != '\r' && b != '\n' {
335				continue
336			}
337			segment := string(s.buf[start:i])
338			start = i + 1
339			if event := parseGitProgressLine(segment); event != nil && s.onEvent != nil {
340				s.onEvent(event)
341			}
342		}
343		s.buf = s.buf[start:]
344	
345		return len(p), nil
346	}
347	
348	// formatPushProgressDetail renders a gitProgressEvent as the short live
349	// detail string shown next to the pushReporter's prefix (e.g. "writing
350	// 40/47 objects"). Returns "" for phases/events that don't carry enough
351	// information to render (e.g. a bare "Enumerating objects: N" line with no
352	// current count yet).
353	func formatPushProgressDetail(event *gitProgressEvent) string {
354		switch event.Phase {
355		case gitProgressPhaseCounting:
356			if event.Current > 0 {
357				return fmt.Sprintf("counting objects: %d", event.Current)
358			}
359			if event.Total > 0 {
360				return fmt.Sprintf("counting objects: %d", event.Total)
361			}
362			return ""
363		case gitProgressPhaseCompressing:
364			if event.Total == 0 {
365				return ""
366			}
367			return fmt.Sprintf("compressing %d/%d", event.Current, event.Total)
368		case gitProgressPhaseWriting:
369			if event.Total == 0 {
370				return ""
371			}
372			return fmt.Sprintf("writing %d/%d objects", event.Current, event.Total)
373		default:
374			return ""
375		}
376	}
377	
378	// displayGitProgress writes human-friendly git transfer progress lines to w.
379	func displayGitProgress(w io.Writer, stderr string) {
380		styles := pushProgressStylesFor(w, false)
381		lastPhase := gitProgressPhase("")
382		// git emits both "Enumerating objects: N, done." and "Counting objects:
383		// 100% (N/N), done." — parseGitProgressLine maps both to
384		// gitProgressPhaseCounting with Done=true, so without this guard the loop
385		// below prints the "counting objects" Done summary twice. printed tracks
386		// which phases already had their one-time Done summary printed so each
387		// phase surfaces at most once per call, no matter how many raw git lines
388		// mapped to it.
389		printed := make(map[gitProgressPhase]bool)
390		for _, line := range strings.FieldsFunc(stderr, func(r rune) bool { return r == '\n' || r == '\r' }) {
391			event := parseGitProgressLine(line)
392			if event == nil {
393				continue
394			}
395			if !event.Done && event.Phase == lastPhase {
396				continue
397			}
398			lastPhase = event.Phase
399			if event.Done {
400				if printed[event.Phase] {
401					continue
402				}
403				printed[event.Phase] = true
404			}
405	
406			switch event.Phase {
407			case gitProgressPhaseCounting:
408				if event.Done {
409					fmt.Fprintf(w, "         %s\n", styles.dim(fmt.Sprintf("counting objects: %d", event.Total)))
410				}
411			case gitProgressPhaseCompressing:
412				if event.Done {
413					fmt.Fprintf(w, "         %s\n", styles.dim(fmt.Sprintf("compressing: %d/%d", event.Current, event.Total)))
414				}
415			case gitProgressPhaseWriting:
416				if event.Done {
417					parts := []string{fmt.Sprintf("writing: %d objects", event.Total)}
418					if event.Bytes != "" {
419						parts = append(parts, event.Bytes)
420					}
421					if event.Speed != "" {
422						parts = append(parts, event.Speed)
423					}
424					fmt.Fprintf(w, "         %s %s\n",
425						styles.dim(strings.Join(parts, ", ")+"..."),
426						styles.green("done"))
427				}
428			}
429		}
430	}
431	
432	// logGitProgress parses git `--progress` transfer stderr and records each
433	// phase transition as operational metadata (phase, counts, bytes) to the
434	// debug log. Unlike displayGitProgress, it writes to NO io.Writer — this is a
435	// file-logging sink only, used on paths that keep the terminal quiet.
436	func logGitProgress(ctx context.Context, stderr string) {
437		lastPhase := gitProgressPhase("")
438		for _, line := range strings.FieldsFunc(stderr, func(r rune) bool { return r == '\n' || r == '\r' }) {
439			event := parseGitProgressLine(line)
440			if event == nil {
441				continue
442			}
443			if !event.Done && event.Phase == lastPhase {
444				continue
445			}
446			lastPhase = event.Phase
447	
448			attrs := []any{
449				slog.String("phase", string(event.Phase)),
450				slog.Bool("done", event.Done),
451				slog.Int("total", event.Total),
452			}
453			if event.Percent > 0 {
454				attrs = append(attrs, slog.Int("percent", event.Percent))
455			}
456			if event.Current > 0 {
457				attrs = append(attrs, slog.Int("current", event.Current))
458			}
459			if event.Bytes != "" {
460				attrs = append(attrs, slog.String("bytes", event.Bytes))
461			}
462			if event.Speed != "" {
463				attrs = append(attrs, slog.String("speed", event.Speed))
464			}
465			logging.Debug(ctx, "git push transfer", attrs...)
466		}
467	}
468	
469	func formatPushTimeRange(earliest, latest time.Time) string {
470		if earliest.Equal(latest) {
471			return formatPushTime(earliest)
472		}
473		if formatPushDate(earliest) == formatPushDate(latest) {
474			return formatPushHM(earliest) + " ~ " + formatPushHM(latest)
475		}
476		return formatPushDate(earliest) + " ~ " + formatPushDate(latest)
477	}
478	
479	func formatPushTime(d time.Time) string {
480		now := time.Now()
481		diffDays := int(now.Sub(d).Hours() / 24)
482		if diffDays <= 0 && now.Before(d.Add(24*time.Hour)) {
483			return formatPushHM(d)
484		}
485		if diffDays == 1 {
486			return "yesterday"
487		}
488		if diffDays > 1 {
489			return fmt.Sprintf("%d days ago", diffDays)
490		}
491		return formatPushHM(d)
492	}
493	
494	func formatPushHM(d time.Time) string {
495		return fmt.Sprintf("%02d:%02d", d.Hour(), d.Minute())
496	}
497	
498	func formatPushDate(d time.Time) string {
499		return fmt.Sprintf("%04d-%02d-%02d", d.Year(), int(d.Month()), d.Day())
500	}
501	
502	func elapsedPushSec(start time.Time) string {
503		sec := int(time.Since(start).Round(time.Second) / time.Second)
504		return fmt.Sprintf("%ds", sec)
505	}
506	
507	func writePushFinishLine(ctx context.Context, w io.Writer, result pushResult, start time.Time, target string) {
508		styles := pushProgressStylesFor(w, false)
509		if result.upToDate {
510			fmt.Fprintf(w, "         %s\n", styles.dim("already up-to-date"))
511			return
512		}
513		fmt.Fprintf(w, "         %s %s\n", styles.green("done"), styles.dim("("+elapsedPushSec(start)+")"))
514		printSettingsCommitHint(ctx, target)
515	}
516	
517	func writePushConflictLine(w io.Writer, start time.Time) {
518		styles := pushProgressStylesFor(w, false)
519		fmt.Fprintf(w, "         %s %s\n", styles.yellow("conflict"), styles.dim("("+elapsedPushSec(start)+")"))
520	}
521

