package strategy

import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"regexp"
	"strconv"
	"strings"
	"time"

	"charm.land/lipgloss/v2"

	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/trailers"
)

const maxDisplayedPushSessions = 5

type gitProgressPhase string

const (
	gitProgressPhaseCounting    gitProgressPhase = "counting"
	gitProgressPhaseCompressing gitProgressPhase = "compressing"
	gitProgressPhaseWriting     gitProgressPhase = "writing"
)

// gitProgressEvent is a parsed line from git push/fetch --progress stderr.
type gitProgressEvent struct {
	Phase   gitProgressPhase
	Percent int
	Current int
	Total   int
	Bytes   string
	Speed   string
	Done    bool
}

// sessionSummary aggregates unpushed checkpoint commits for one session.
type sessionSummary struct {
	SessionID       string
	CheckpointCount int
	CommitCount     int
	EarliestTime    time.Time
	LatestTime      time.Time
}

// formatSessionTreeOpts configures formatSessionTree output.
type formatSessionTreeOpts struct {
	TotalCommits int
	NoColor      bool
	IsNewBranch  bool
	// Writer is the target the formatted lines will actually be printed to.
	// Styling decisions (pushProgressStylesFor) must be computed against this
	// writer, not io.Discard, or ANSI styling never applies even when the
	// caller prints to a real, style-capable terminal. Defaults to
	// io.Discard (no styling) if left unset.
	Writer io.Writer
}

type pushProgressStyles struct {
	dim    func(string) string
	green  func(string) string
	yellow func(string) string
}

func pushProgressStylesFor(w io.Writer, noColor bool) pushProgressStyles {
	if noColor || !interactive.ShouldStyle(w) {
		return pushProgressStyles{
			dim:    func(s string) string { return s },
			green:  func(s string) string { return s },
			yellow: func(s string) string { return s },
		}
	}
	dimStyle := lipgloss.NewStyle().Faint(true)
	greenStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("2"))
	yellowStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("3"))
	return pushProgressStyles{
		dim:    func(s string) string { return dimStyle.Render(s) },
		green:  func(s string) string { return greenStyle.Render(s) },
		yellow: func(s string) string { return yellowStyle.Render(s) },
	}
}

var (
	checkpointMsgRE  = regexp.MustCompile(`^Checkpoint: ([0-9a-f]+)`)
	finalizeMsgRE    = regexp.MustCompile(`^Finalize transcript for Checkpoint: ([0-9a-f]+)`)
	updateMsgRE      = regexp.MustCompile(`^Update (?:summary|checkpoint summary) for (?:checkpoint )?([0-9a-f]+)`)
	sessionTrailerRE = regexp.MustCompile(regexp.QuoteMeta(trailers.SessionTrailerKey) + `: (.+)`)

	gitEnumeratingRE  = regexp.MustCompile(`^Enumerating objects:\s*(\d+)`)
	gitCountingRE     = regexp.MustCompile(`^Counting objects:\s*(\d+)%\s*\((\d+)/(\d+)\)`)
	gitCompressingRE  = regexp.MustCompile(`^Compressing objects:\s*(\d+)%\s*\((\d+)/(\d+)\)`)
	gitWritingRE      = regexp.MustCompile(`^Writing objects:\s*(\d+)%\s*\((\d+)/(\d+)\)`)
	gitWritingBytesRE = regexp.MustCompile(`(\d+(?:\.\d+)?\s*[KMG]iB)(?:\s*\|\s*(\d+(?:\.\d+)?\s*[KMG]iB/s))?`)
)

type pushSummaryAccumulator struct {
	checkpoints map[string]struct{}
	commitCount int
	earliest    time.Time
	latest      time.Time
}

// parsePushSummaryFromLog groups git log lines by Entire-Session trailer.
// Input format: hash|subject|trailers|authorDate (one commit per line).
func parsePushSummaryFromLog(gitLogOutput string) []sessionSummary {
	gitLogOutput = strings.TrimSpace(gitLogOutput)
	if gitLogOutput == "" {
		return nil
	}

	checkpointToSession := make(map[string]string)
	sessionMap := make(map[string]*pushSummaryAccumulator)

	for _, line := range strings.Split(gitLogOutput, "\n") {
		parts := strings.Split(line, "|")
		if len(parts) < 4 {
			continue
		}
		subject := parts[1]
		body := parts[2]
		when, err := time.Parse(time.RFC3339, parts[3])
		if err != nil {
			continue
		}

		var checkpointID string
		if m := checkpointMsgRE.FindStringSubmatch(subject); m != nil {
			checkpointID = m[1]
		} else if m := finalizeMsgRE.FindStringSubmatch(subject); m != nil {
			checkpointID = m[1]
		} else if m := updateMsgRE.FindStringSubmatch(subject); m != nil {
			checkpointID = m[1]
		}

		sessionID := ""
		if m := sessionTrailerRE.FindStringSubmatch(body); m != nil {
			sessionID = strings.TrimSpace(m[1])
			if checkpointID != "" {
				checkpointToSession[checkpointID] = sessionID
			}
		} else if checkpointID != "" {
			sessionID = checkpointToSession[checkpointID]
		}
		if sessionID == "" {
			sessionID = "unknown"
		}

		entry, ok := sessionMap[sessionID]
		if !ok {
			checkpoints := map[string]struct{}{}
			if checkpointID != "" {
				checkpoints[checkpointID] = struct{}{}
			}
			sessionMap[sessionID] = &pushSummaryAccumulator{
				checkpoints: checkpoints,
				commitCount: 1,
				earliest:    when,
				latest:      when,
			}
			continue
		}

		entry.commitCount++
		if checkpointID != "" {
			entry.checkpoints[checkpointID] = struct{}{}
		}
		if when.Before(entry.earliest) {
			entry.earliest = when
		}
		if when.After(entry.latest) {
			entry.latest = when
		}
	}

	results := make([]sessionSummary, 0, len(sessionMap))
	for sessionID, entry := range sessionMap {
		results = append(results, sessionSummary{
			SessionID:       sessionID,
			CheckpointCount: len(entry.checkpoints),
			CommitCount:     entry.commitCount,
			EarliestTime:    entry.earliest,
			LatestTime:      entry.latest,
		})
	}
	sortSessionSummariesByLatest(results)
	return results
}

func sortSessionSummariesByLatest(results []sessionSummary) {
	for i := 0; i < len(results); i++ {
		for j := i + 1; j < len(results); j++ {
			if results[j].LatestTime.After(results[i].LatestTime) {
				results[i], results[j] = results[j], results[i]
			}
		}
	}
}

// formatSessionTree renders session summaries as indented stderr lines.
func formatSessionTree(summaries []sessionSummary, opts formatSessionTreeOpts) []string {
	w := opts.Writer
	if w == nil {
		w = io.Discard
	}
	styles := pushProgressStylesFor(w, opts.NoColor)
	lines := make([]string, 0, len(summaries)+3)

	branchLabel := ""
	if opts.IsNewBranch {
		branchLabel = "new branch, "
	}
	header := fmt.Sprintf("%s Checkpoint push: %s%d commits, %d sessions",
		styles.dim("[entire]"), branchLabel, opts.TotalCommits, len(summaries))
	lines = append(lines, header)

	displayed := summaries
	remaining := 0
	if len(summaries) > maxDisplayedPushSessions {
		displayed = summaries[:maxDisplayedPushSessions]
		remaining = len(summaries) - maxDisplayedPushSessions
	}

	for i, s := range displayed {
		isLast := i == len(displayed)-1 && remaining == 0
		connector := "├─"
		if isLast {
			connector = "└─"
		}
		cpLabel := fmt.Sprintf("%d checkpoints", s.CheckpointCount)
		if s.CheckpointCount == 1 {
			cpLabel = "1 checkpoint"
		}
		timeLabel := formatPushTimeRange(s.EarliestTime, s.LatestTime)
		line := fmt.Sprintf("         %s %s  %s  %s",
			styles.dim(connector), s.SessionID, styles.dim(cpLabel), styles.dim("("+timeLabel+")"))
		lines = append(lines, line)
	}

	if remaining > 0 {
		lines = append(lines, fmt.Sprintf("         %s %s",
			styles.dim("├─"), styles.dim(fmt.Sprintf("... and %d more sessions", remaining))))
		oldest := summaries[len(summaries)-1]
		lines = append(lines, fmt.Sprintf("         %s %s",
			styles.dim("└─"), styles.dim("(oldest: "+formatPushDate(oldest.EarliestTime)+")")))
	}

	return lines
}

func parseGitProgressLine(line string) *gitProgressEvent {
	trimmed := strings.TrimSpace(line)

	if m := gitEnumeratingRE.FindStringSubmatch(trimmed); m != nil {
		total, err := strconv.Atoi(m[1])
		if err != nil {
			return nil
		}
		return &gitProgressEvent{
			Phase: gitProgressPhaseCounting,
			Total: total,
			Done:  strings.Contains(trimmed, "done"),
		}
	}

	if m := gitCountingRE.FindStringSubmatch(trimmed); m != nil {
		return parsePercentGitProgressEvent(gitProgressPhaseCounting, m, trimmed)
	}
	if m := gitCompressingRE.FindStringSubmatch(trimmed); m != nil {
		return parsePercentGitProgressEvent(gitProgressPhaseCompressing, m, trimmed)
	}
	if m := gitWritingRE.FindStringSubmatch(trimmed); m != nil {
		event := parsePercentGitProgressEvent(gitProgressPhaseWriting, m, trimmed)
		if bm := gitWritingBytesRE.FindStringSubmatch(trimmed); bm != nil {
			event.Bytes = bm[1]
			if len(bm) > 2 {
				event.Speed = bm[2]
			}
		}
		return event
	}

	return nil
}

func parsePercentGitProgressEvent(phase gitProgressPhase, m []string, trimmed string) *gitProgressEvent {
	percent, err := strconv.Atoi(m[1])
	if err != nil {
		return nil
	}
	current, err := strconv.Atoi(m[2])
	if err != nil {
		return nil
	}
	total, err := strconv.Atoi(m[3])
	if err != nil {
		return nil
	}
	return &gitProgressEvent{
		Phase:   phase,
		Percent: percent,
		Current: current,
		Total:   total,
		Done:    strings.Contains(trimmed, "done"),
	}
}

// gitProgressStreamer is an io.Writer that live-parses git `--progress`
// stderr bytes as they arrive, without waiting for the push to finish. git
// emits progress as segments separated by '\r' (in-place updates) or '\n'
// (a completed line, e.g. the final "done." for a phase). Write accumulates
// bytes across calls — a chunk boundary can land mid-line — and parses each
// completed segment as soon as its terminator arrives, invoking onEvent for
// every line that parses to a non-nil *gitProgressEvent. Leftover partial
// bytes (after the last terminator in the chunk) are buffered for the next
// Write. Not safe for concurrent Write calls; callers must serialize writes
// (e.g. a single git stderr pipe copied by one goroutine).
type gitProgressStreamer struct {
	buf     []byte
	onEvent func(*gitProgressEvent)
}

// Write implements io.Writer. It never returns an error — parse failures are
// simply skipped — so it never causes the underlying io.MultiWriter copy (see
// checkpoint/remote.PushOptions.ProgressWriter) to abort the push.
func (s *gitProgressStreamer) Write(p []byte) (int, error) {
	s.buf = append(s.buf, p...)

	start := 0
	for i, b := range s.buf {
		if b != '\r' && b != '\n' {
			continue
		}
		segment := string(s.buf[start:i])
		start = i + 1
		if event := parseGitProgressLine(segment); event != nil && s.onEvent != nil {
			s.onEvent(event)
		}
	}
	s.buf = s.buf[start:]

	return len(p), nil
}

// formatPushProgressDetail renders a gitProgressEvent as the short live
// detail string shown next to the pushReporter's prefix (e.g. "writing
// 40/47 objects"). Returns "" for phases/events that don't carry enough
// information to render (e.g. a bare "Enumerating objects: N" line with no
// current count yet).
func formatPushProgressDetail(event *gitProgressEvent) string {
	switch event.Phase {
	case gitProgressPhaseCounting:
		if event.Current > 0 {
			return fmt.Sprintf("counting objects: %d", event.Current)
		}
		if event.Total > 0 {
			return fmt.Sprintf("counting objects: %d", event.Total)
		}
		return ""
	case gitProgressPhaseCompressing:
		if event.Total == 0 {
			return ""
		}
		return fmt.Sprintf("compressing %d/%d", event.Current, event.Total)
	case gitProgressPhaseWriting:
		if event.Total == 0 {
			return ""
		}
		return fmt.Sprintf("writing %d/%d objects", event.Current, event.Total)
	default:
		return ""
	}
}

// displayGitProgress writes human-friendly git transfer progress lines to w.
func displayGitProgress(w io.Writer, stderr string) {
	styles := pushProgressStylesFor(w, false)
	lastPhase := gitProgressPhase("")
	// git emits both "Enumerating objects: N, done." and "Counting objects:
	// 100% (N/N), done." — parseGitProgressLine maps both to
	// gitProgressPhaseCounting with Done=true, so without this guard the loop
	// below prints the "counting objects" Done summary twice. printed tracks
	// which phases already had their one-time Done summary printed so each
	// phase surfaces at most once per call, no matter how many raw git lines
	// mapped to it.
	printed := make(map[gitProgressPhase]bool)
	for _, line := range strings.FieldsFunc(stderr, func(r rune) bool { return r == '\n' || r == '\r' }) {
		event := parseGitProgressLine(line)
		if event == nil {
			continue
		}
		if !event.Done && event.Phase == lastPhase {
			continue
		}
		lastPhase = event.Phase
		if event.Done {
			if printed[event.Phase] {
				continue
			}
			printed[event.Phase] = true
		}

		switch event.Phase {
		case gitProgressPhaseCounting:
			if event.Done {
				fmt.Fprintf(w, "         %s\n", styles.dim(fmt.Sprintf("counting objects: %d", event.Total)))
			}
		case gitProgressPhaseCompressing:
			if event.Done {
				fmt.Fprintf(w, "         %s\n", styles.dim(fmt.Sprintf("compressing: %d/%d", event.Current, event.Total)))
			}
		case gitProgressPhaseWriting:
			if event.Done {
				parts := []string{fmt.Sprintf("writing: %d objects", event.Total)}
				if event.Bytes != "" {
					parts = append(parts, event.Bytes)
				}
				if event.Speed != "" {
					parts = append(parts, event.Speed)
				}
				fmt.Fprintf(w, "         %s %s\n",
					styles.dim(strings.Join(parts, ", ")+"..."),
					styles.green("done"))
			}
		}
	}
}

// logGitProgress parses git `--progress` transfer stderr and records each
// phase transition as operational metadata (phase, counts, bytes) to the
// debug log. Unlike displayGitProgress, it writes to NO io.Writer — this is a
// file-logging sink only, used on paths that keep the terminal quiet.
func logGitProgress(ctx context.Context, stderr string) {
	lastPhase := gitProgressPhase("")
	for _, line := range strings.FieldsFunc(stderr, func(r rune) bool { return r == '\n' || r == '\r' }) {
		event := parseGitProgressLine(line)
		if event == nil {
			continue
		}
		if !event.Done && event.Phase == lastPhase {
			continue
		}
		lastPhase = event.Phase

		attrs := []any{
			slog.String("phase", string(event.Phase)),
			slog.Bool("done", event.Done),
			slog.Int("total", event.Total),
		}
		if event.Percent > 0 {
			attrs = append(attrs, slog.Int("percent", event.Percent))
		}
		if event.Current > 0 {
			attrs = append(attrs, slog.Int("current", event.Current))
		}
		if event.Bytes != "" {
			attrs = append(attrs, slog.String("bytes", event.Bytes))
		}
		if event.Speed != "" {
			attrs = append(attrs, slog.String("speed", event.Speed))
		}
		logging.Debug(ctx, "git push transfer", attrs...)
	}
}

func formatPushTimeRange(earliest, latest time.Time) string {
	if earliest.Equal(latest) {
		return formatPushTime(earliest)
	}
	if formatPushDate(earliest) == formatPushDate(latest) {
		return formatPushHM(earliest) + " ~ " + formatPushHM(latest)
	}
	return formatPushDate(earliest) + " ~ " + formatPushDate(latest)
}

func formatPushTime(d time.Time) string {
	now := time.Now()
	diffDays := int(now.Sub(d).Hours() / 24)
	if diffDays <= 0 && now.Before(d.Add(24*time.Hour)) {
		return formatPushHM(d)
	}
	if diffDays == 1 {
		return "yesterday"
	}
	if diffDays > 1 {
		return fmt.Sprintf("%d days ago", diffDays)
	}
	return formatPushHM(d)
}

func formatPushHM(d time.Time) string {
	return fmt.Sprintf("%02d:%02d", d.Hour(), d.Minute())
}

func formatPushDate(d time.Time) string {
	return fmt.Sprintf("%04d-%02d-%02d", d.Year(), int(d.Month()), d.Day())
}

func elapsedPushSec(start time.Time) string {
	sec := int(time.Since(start).Round(time.Second) / time.Second)
	return fmt.Sprintf("%ds", sec)
}

func writePushFinishLine(ctx context.Context, w io.Writer, result pushResult, start time.Time, target string) {
	styles := pushProgressStylesFor(w, false)
	if result.upToDate {
		fmt.Fprintf(w, "         %s\n", styles.dim("already up-to-date"))
		return
	}
	fmt.Fprintf(w, "         %s %s\n", styles.green("done"), styles.dim("("+elapsedPushSec(start)+")"))
	printSettingsCommitHint(ctx, target)
}

func writePushConflictLine(w io.Writer, start time.Time) {
	styles := pushProgressStylesFor(w, false)
	fmt.Fprintf(w, "         %s %s\n", styles.yellow("conflict"), styles.dim("("+elapsedPushSec(start)+")"))
}

package strategy

import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"sync"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// pushShouldReveal reports whether the pre-push progress line should be shown:
// only when styled (ANSI-capable per interactive.ShouldStyle — respects
// NO_COLOR and TERM=cygwin, not merely "stderr is a terminal"), and only once
// the push has run long enough to feel stuck.
func pushShouldReveal(elapsed, threshold time.Duration, styled bool) bool {
	return styled && elapsed >= threshold
}

// pushReporter is a threshold-gated, single-in-place-line progress reporter
// for the pre-push checkpoint sync. It always logs to file via logging.Debug,
// but only writes to its terminal writer once the push has run long enough to
// feel stuck (and never at all when styled is false) — agents and CI must see
// zero bytes.
type pushReporter struct {
	ctx       context.Context
	w         io.Writer
	styled    bool
	threshold time.Duration
	start     time.Time

	mu       sync.Mutex
	revealed bool
	prefix   string
	detail   string

	done    chan struct{}
	stopped chan struct{}
}

// newPushReporter creates a pushReporter and starts its background reveal
// goroutine. Callers must call finish to stop the goroutine and print the
// persistent summary line.
func newPushReporter(ctx context.Context, w io.Writer, styled bool, threshold time.Duration) *pushReporter {
	r := &pushReporter{
		ctx:       ctx,
		w:         w,
		styled:    styled,
		threshold: threshold,
		start:     time.Now(),
		done:      make(chan struct{}),
		stopped:   make(chan struct{}),
	}
	go r.run()
	return r
}

// run waits until the threshold elapses, then ticks ~1s, redrawing the
// in-place line while the reporter is not yet done.
func (r *pushReporter) run() {
	defer close(r.stopped)

	timer := time.NewTimer(r.threshold)
	defer timer.Stop()

	select {
	case <-r.done:
		return
	case <-timer.C:
	}

	r.mu.Lock()
	r.maybeReveal()
	r.mu.Unlock()

	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()

	for {
		select {
		case <-r.done:
			return
		case <-ticker.C:
			r.mu.Lock()
			r.maybeReveal()
			r.mu.Unlock()
		}
	}
}

// maybeReveal writes the current in-place line when reveal conditions are
// met. Callers must hold r.mu.
func (r *pushReporter) maybeReveal() {
	if !pushShouldReveal(time.Since(r.start), r.threshold, r.styled) {
		return
	}
	r.revealed = true
	r.redrawLocked()
}

// redrawLocked writes the current in-place line. Callers must hold r.mu.
func (r *pushReporter) redrawLocked() {
	if !r.styled {
		return
	}
	elapsed := int(time.Since(r.start).Seconds())
	if r.detail != "" {
		fmt.Fprintf(r.w, "\r[entire] %s… %s (%ds)\033[K", r.prefix, r.detail, elapsed)
	} else {
		fmt.Fprintf(r.w, "\r[entire] %s… (%ds)\033[K", r.prefix, elapsed)
	}
}

// phase sets the current prefix text (e.g. "syncing 12 checkpoints"). It
// always logs to file; if the line is already revealed, it redraws
// immediately.
func (r *pushReporter) phase(prefix string) {
	logging.Debug(r.ctx, "checkpoint push progress", slog.String("phase", prefix))

	r.mu.Lock()
	defer r.mu.Unlock()
	r.prefix = prefix
	if r.revealed {
		r.redrawLocked()
	}
}

// setDetail updates the live transfer detail (e.g. "writing 40/47 objects")
// shown alongside the prefix, redrawing immediately if the line is already
// revealed. Deliberately does not log to file on every call — it is driven by
// git's --progress stream, which ticks far more often than is useful in the
// debug log; logGitProgress records the transfer detail to file once, after
// the push completes.
func (r *pushReporter) setDetail(detail string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.detail = detail
	if r.revealed {
		r.redrawLocked()
	}
}

// finish stops the reveal goroutine and, if the line was ever revealed,
// prints a PERSISTENT final summary line (trailing newline, so it stays in
// the user's scrollback rather than being erased) and logs the final summary
// to file. Stays completely silent when the line was never revealed —
// agents/CI/fast pushes must see zero bytes.
func (r *pushReporter) finish(summary string) {
	close(r.done)
	<-r.stopped

	r.mu.Lock()
	if r.revealed && r.styled {
		if summary == "" {
			// No summary (e.g. an aborted/failed push whose caller prints its
			// own error next): just clear the in-place line, don't emit a
			// content-less "[entire]  (Ns)" persistent line.
			fmt.Fprint(r.w, "\r\033[K")
		} else {
			elapsed := int(time.Since(r.start).Seconds())
			fmt.Fprintf(r.w, "\r[entire] %s (%ds)\033[K\n", summary, elapsed)
		}
	}
	r.mu.Unlock()

	logging.Debug(r.ctx, "checkpoint push finished", slog.String("summary", summary))
}

