12	// syncBuffer is a mutex-guarded io.Writer for tests that read a buffer
13	// concurrently with a goroutine writing to it (e.g. pushReporter's reveal
14	// goroutine). Reading a plain bytes.Buffer while such a goroutine runs is a
15	// data race; syncBuffer serializes access so polling is race-safe.
16	type syncBuffer struct {
17		mu  sync.Mutex
18		buf bytes.Buffer
19	}
20	
21	func (s *syncBuffer) Write(p []byte) (int, error) {
22		s.mu.Lock()
23		defer s.mu.Unlock()
24		return s.buf.Write(p)
25	}
26	
27	func (s *syncBuffer) String() string {
28		s.mu.Lock()
29		defer s.mu.Unlock()
30		return s.buf.String()
31	}
