33	// waitForContains polls buf until it contains substr, rather than sleeping a
34	// fixed duration: under saturated -race CI load the reporter's background
35	// goroutine may not be scheduled within any fixed window. buf.String() is
36	// mutex-guarded, so polling concurrently with the goroutine's writes is
37	// race-safe.
38	func waitForContains(t *testing.T, buf *syncBuffer, substr string) {
39		t.Helper()
40		deadline := time.Now().Add(2 * time.Second)
41		for {
42			out := buf.String()
43			if strings.Contains(out, substr) {
44				return
45			}
46			if time.Now().After(deadline) {
47				t.Fatalf("timed out waiting for %q, got %q", substr, out)
48			}
49			time.Sleep(time.Millisecond)
50		}
51	}
